repo.invoices.py:
"""Invoice records."""


class Invoice:
    def __init__(self, client, due):
        self.client = client
        self.due = due

    def __repr__(self):
        return "Invoice(%r, %r)" % (self.client, self.due)


ROWS = [('ivory', 47), ('hale', 5), ('ivory', 8), ('juno', 46), ('hale', 53), ('hale', 43), ('ivory', 28)]


def load_invoices():
    """Yield the stored invoices one at a time."""
    for client, due in ROWS:
        yield Invoice(client, due)

