"""Labels for invoices."""


def label_invoices(names, invoices):
    """Return (lookup, lines): a name -> due dict and one 'name: due' line per invoice."""
    pairs = zip(names, (x.due for x in invoices))
    lookup = dict(pairs)
    lines = ["%s: %s" % (name, value) for name, value in pairs]
    return lookup, lines


def name_list(names):
    """Return the names joined by commas."""
    return ", ".join(names)


def describe_invoice(invoice):
    """Return a one-line description of a invoice."""
    return "%s: %s" % (invoice.client, invoice.due)


def largest_due(invoices):
    """Return the largest due, or None when there are no invoices."""
    values = [x.due for x in invoices]
    return max(values) if values else None

